## Code Example
```javascript
// Routing and retrieval pipeline
const detectLanguage = (query) => langdetect.detect(query)[0].lang;

const routeQuery = async (query) => {
  const lang = detectLanguage(query);
  const embedding = await embedQuery(query);
  const results = await vectorStore.search(embedding, { k: 5, filter: { lang } });
  const citations = results.map(r => ({ source: r.metadata.source, text: r.text }));

  if (results.some(r => r.metadata.confidence < 0.7)) {
    return { status: 'escalate', citations };
  }

  return { status: 'respond', citations, context: results };
};
```

## Why This Is Asked
